=== file: main.loom ===
budget { tokens: 6000  calls: 8 }

intentclassifier PolicyTriage {
    model: "gpt-6-luna"
    choose abuse: abusive | not_abusive
    choose visibility: required | not_required
    confidence at least 0.8 else escalate
}

tool PlatformRead {
    use: openapi
    spec: env.PLATFORM_API_SPEC
    auth_header: "Authorization"
    auth_value: env.PLATFORM_API_TOKEN
}

tool ReviewQueue {
    use: webhook
    url: env.REVIEW_QUEUE_URL
    format: json
}

tool TemporaryHide {
    use: openapi
    spec: env.PLATFORM_API_SPEC
    auth_header: "Authorization"
    auth_value: env.PLATFORM_API_TOKEN
}

tool RemoveComment {
    use: openapi
    spec: env.PLATFORM_API_SPEC
    auth_header: "Authorization"
    auth_value: env.PLATFORM_API_TOKEN
}

workflow Main(comment_payload_record, published_policy_document) {
    set classifier_input_packet = {
        comment: comment_payload_record,
        policy: published_policy_document
    }

    intentclassify PolicyTriage on classifier_input_packet -> triage_record retry 1 backoff 2s timeout 20s on_failure {
        note "Classification failed. Do not change comment visibility; route this event to a human operator."
        halt "The moderation classification failed."
    }

    alt (triage_record.visibility == "unsure") {
        human_prompt "The policy requirement for temporary hiding is unclear. Should this comment be temporarily hidden while it awaits review? Answer required or not_required. Leave it visible unless you confirm required." -> policy_review_choice_text
        alt (policy_review_choice_text == "required") {
            note "A policy reviewer confirmed temporary hiding is required. Request human approval before any visibility change."
            human_prompt "The policy reviewer confirmed that temporary hiding is required. Approve the temporary hide? Answer yes or no." -> hide_approval_choice_text
            alt (hide_approval_choice_text == "yes") {
                note "Temporary hide approved. The TemporaryHide connector must be invoked by the configured moderation application."
            } else {
                note "Temporary hide was not approved. Leave the comment visible."
            }
        } else {
            note "Temporary hiding was not confirmed. Leave the comment visible."
        }
    } else {
        alt (triage_record.visibility == "required") {
            human_prompt "The published policy says temporary hiding is required. Approve the temporary hide? Answer yes or no." -> hide_approval_choice_text
            alt (hide_approval_choice_text == "yes") {
                note "Temporary hide approved. The TemporaryHide connector must be invoked by the configured moderation application."
            } else {
                note "Temporary hide was not approved. Leave the comment visible."
            }
        } else {
            note "The published policy does not require temporary hiding. Leave the comment visible."
        }
    }

    alt (triage_record.abuse == "not_abusive") {
        note "The comment was confidently classified as not abusive. No moderation change is requested."
    } else {
        human_prompt "This comment is flagged for moderator review. Choose exactly remove or keep. A remove choice is the only authorization to remove it." -> moderator_decision_text
        alt (moderator_decision_text == "remove") {
            note "The moderator explicitly chose removal. The RemoveComment connector must be invoked by the configured moderation application."
        } else {
            note "The moderator did not choose remove. Keep the comment in place."
        }
    }

    return "Moderation review completed."
}
